        # simpler: enumerate all L positions: cells (a,b),(a+1,b),(a,b+1) missing (a,a+1)... just enumerate triples
        for (r,c) in sorted(rem):
            for m in [(0,0),(0,1),(-1,0),(-1,-1)]:
                trio={}
                trio[(0,0)]=(r,c)   # top-left base
                trio[(0,1)]=(r,c+1)
                trio[(-1,0)]=(r-1,c)
                trio[(-1,-1)]=(r-1,c-1)
                tri=[p for p in trio.values()]
                if all(p in rem for p in tri): cand.append(('l',m,tri))
        if not cand: return None
        # prefer square
        sc=[x for x in cand if x[0]=='sq']
        lc=[x for x in cand if x[0]=='l']
        if sc:
            ch=max(sc,key=lambda x:len(set(x[1]))) 
        else:
            ch=max(lc,key=lambda x:len(set(x[2])))
        kind,v,hh=ch[0],ch[1],ch[2] if kind=='l' else ch[1]
        res.append((kind,hh))
        newrem=set(rem)-set(hh)
        rr=bt(newrem)
        if rr is None: return None
        return [(kind,hh)]+rr
    return bt(S)

